def wigner_3j(J: int, d_in: int, d_out: int, device=None, dtype=torch.float64):
    """The `(2*d_out+1, 2*d_in+1, 2*J+1)` coefficient tensor, densified."""
    key = f"{J},{d_in},{d_out}"
    if key not in _SPARSE:
        raise KeyError(
            f"no baked Wigner 3j for (J={J}, d_in={d_in}, d_out={d_out}); "
            "this table covers degrees up to 2. Regenerate with a larger MAXD."
        )
    shape, entries = _SPARSE[key]
    # math.prod, not torch.tensor(shape).prod().item(): a `.item()` here is a
    # device-to-host sync that dynamo cannot trace, and it showed up as 11 graph
    # breaks before being fixed. The shape is Python ints; keep it in Python.
    n = 1
    for d in shape:
        n *= d
    flat = torch.zeros(n, dtype=dtype, device=device)
    if entries:
        idx = torch.tensor([i for i, _ in entries], dtype=torch.long, device=device)
        val = torch.tensor([v for _, v in entries], dtype=dtype, device=device)
        flat[idx] = val
    return flat.view(shape)


def _regenerate(maxd=2):
    """Re-emit this file from e3nn. Used only by the maintainer."""
    import e3nn.o3 as o3
    out = {}
    for d_in in range(maxd + 1):
        for d_out in range(maxd + 1):
            for J in range(abs(d_in - d_out), d_in + d_out + 1):
                out[f"{J},{d_in},{d_out}"] = o3.wigner_3j(
                    J, d_in, d_out, dtype=torch.float64).permute(2, 1, 0)
    return out


if __name__ == "__main__":
    import sys
    if "--regenerate" in sys.argv:
        ref = _regenerate()
        worst = 0.0
        for k, t in ref.items():
            worst = max(worst, (t - wigner_3j(*map(int, k.split(",")))).abs().max().item())
        print(f"baked table matches e3nn, worst |diff| = {worst:.3e} over {len(ref)} entries")
